-- =============================================================================
-- LaptopStore Rollback Seed Script
-- Khôi phục hoàn toàn dữ liệu về trạng thái trước khi chạy seed-products.sql
-- =============================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Xóa các bản ghi phát sinh theo đúng thứ tự khóa ngoại
DELETE FROM reviews WHERE id >= 4;
DELETE FROM stock_log WHERE id >= 3;
DELETE FROM voucher_usage WHERE id >= 3;
DELETE FROM order_status_history WHERE id >= 10;
DELETE FROM payment WHERE id >= 3;
DELETE FROM orderitem WHERE id >= 3;
DELETE FROM orders WHERE id >= 3;
DELETE FROM address WHERE id >= 2;
DELETE FROM user_roles WHERE user_id >= 3;
DELETE FROM users WHERE id >= 3;
DELETE FROM voucher WHERE id >= 2;

-- 2. Khôi phục hoàn toàn bảng product_variant (xóa hết và nạp lại 21 dòng gốc)
DELETE FROM product_variant;
SET @has_idx = (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'product_variant' AND index_name = 'uk_variant_sku');
SET @sql_didx = IF(@has_idx > 0, 'ALTER TABLE product_variant DROP INDEX uk_variant_sku', 'SELECT 1');
PREPARE stmt_didx FROM @sql_didx; EXECUTE stmt_didx; DEALLOCATE PREPARE stmt_didx;

SET @has_sku = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'product_variant' AND column_name = 'sku');
SET @sql_dsku = IF(@has_sku > 0, 'ALTER TABLE product_variant DROP COLUMN sku', 'SELECT 1');
PREPARE stmt_dsku FROM @sql_dsku; EXECUTE stmt_dsku; DEALLOCATE PREPARE stmt_dsku;

SET @has_price = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'product_variant' AND column_name = 'price');
SET @sql_dprc = IF(@has_price > 0, 'ALTER TABLE product_variant DROP COLUMN price', 'SELECT 1');
PREPARE stmt_dprc FROM @sql_dprc; EXECUTE stmt_dprc; DEALLOCATE PREPARE stmt_dprc;

